	if input.Category != nil {
		svcInput.Category = string(*input.Category)
	}
	if input.Event != nil {
		ev, err := mapEventInput(input.Event)
		if err != nil {
			return nil, fmt.Errorf("createTicket: %w", err)
		}
		svcInput.Event = ev
	}

